/* Janela Personagem: tema clássico e confirmação de atributos. */
(function(){'use strict';const C=MythosCore,M=AttributeDraft,$=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attrs=[['forca','Força'],['destreza','Destreza'],['vitalidade','Vitalidade'],['magia','Magia']];
const decimal=(n,d=1)=>n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
class MythosCharacter{
 constructor(game){this.g=game;this.draft=null;game.renderer.hero.addEventListener?.('load',()=>this.paint());}
 dismiss(){this.draft=null;}
 render(message=''){
  const p=this.g.p;if(!M.valid(p,this.draft))this.draft=M.begin(p);const d=this.draft,proposed=M.preview(p,d),s=C.stats(proposed),current=C.stats(p),pending=M.total(d),cap=p.level>=99;
  const hp=Math.min(s.hp,p.hp+s.hp-current.hp),mp=Math.min(s.mp,p.mp+s.mp-current.mp);
  const resource=(name,kind,value,max)=>'<div class="character-resource"><span>'+name+'</span><div class="character-meter '+kind+'"><i style="width:'+Math.max(0,Math.min(100,value/max*100))+'%"></i><b>'+Math.floor(value)+' / '+max+'</b></div></div>';
  const stats=[['Poder primário',decimal(s.power)],['Poder secundário',s.secondaryPower?decimal(s.secondaryPower):'—'],['Defesa física',decimal(s.defense,0)],['Defesa mágica',decimal(s.magicDefense,0)],['Chance crítica',decimal(s.crit*100,0)+'%'],['Esquiva: recarga','10 s'],['Movimento',decimal(C.MOVE_SPEED/32,2)+' m/s']];
  $('modalTitle').textContent='Personagem';
  $('modalBody').innerHTML='<section id="characterRoot" aria-label="Personagem e distribuição de atributos"><button id="characterClose" class="character-close" aria-label="Fechar personagem" title="Fechar [Esc]">×</button><div class="character-content"><h2 class="character-title">Personagem</h2><h3 class="character-name">'+esc(p.name)+'</h3><div class="character-identity"><div class="character-profile"><div class="character-portrait-frame"><canvas id="characterPortrait" width="192" height="192" aria-label="Retrato do Guardião"></canvas></div><strong>Guardião</strong><span>Nível '+p.level+'</span></div><dl><div><dt>Contrato:</dt><dd>Aço</dd></div><div><dt>Guilda:</dt><dd>Nenhuma</dd></div><div><dt>Título:</dt><dd>—</dd></div></dl></div><div class="character-experience"><span>Experiência</span><div class="character-meter xp"><i style="width:'+(cap?100:Math.min(100,p.xp/C.xpFor(p.level)*100))+'%"></i></div><b>'+(cap?'Nível máximo':p.xp+' / '+C.xpFor(p.level))+'</b></div><div class="character-resources">'+resource('Vida','hp',hp,s.hp)+resource('Mana','mp',mp,s.mp)+'</div><div class="character-divider"></div><h3 class="character-section-title">Atributos</h3><p class="character-points">Pontos disponíveis: <b id="characterPoints" aria-live="polite">'+M.remaining(d)+'</b></p><div class="character-attributes">'+attrs.map(([key,name])=>'<div class="character-attribute"><label for="characterValue-'+key+'">'+name+'</label><output id="characterValue-'+key+'" class="'+(d.added[key]?'planned':'')+'" title="Base '+p.attrs[key]+' · Bônus '+(current[key]-p.attrs[key])+' · Prévia +'+d.added[key]+'">'+s[key]+'</output><button id="characterRemove-'+key+'" data-attribute="'+key+'" data-delta="-1" title="Desfazer um ponto adicionado nesta prévia" aria-label="Remover ponto de '+name+'" '+(d.added[key]<1?'disabled':'')+'>−</button><button id="characterAdd-'+key+'" data-attribute="'+key+'" data-delta="1" aria-label="Adicionar ponto de '+name+'" '+(M.remaining(d)<1?'disabled':'')+'>+</button></div>').join('')+'</div><p class="character-preview-note" id="characterStatus" role="status">'+esc(message||(pending?'Prévia da distribuição · '+pending+' ponto'+(pending===1?'':'s')+' pendente'+(pending===1?'':'s'):'Prévia da distribuição'))+'</p><div class="character-actions"><button id="characterCancel" '+(!pending?'disabled':'')+'>Cancelar</button><button id="characterApply" '+(!pending?'disabled':'')+'>Aplicar</button></div><div class="character-divider"></div><h3 class="character-section-title combat-heading">Estatísticas de combate</h3><dl class="character-combat">'+stats.map(([key,value],i)=>'<div class="'+(i===6?'full':'')+'"><dt>'+key+'</dt><dd>'+value+'</dd></div>').join('')+'</dl></div></section>';
  $('characterClose').onclick=()=>this.g.close();
  document.querySelectorAll('[data-attribute]').forEach(b=>b.onclick=()=>{if(this.g.panel!=='character')return;const id=b.id;if(M.adjust(this.g.p,this.draft,b.dataset.attribute,Number(b.dataset.delta))){this.render();$(id)?.focus();}});
  $('characterCancel').onclick=()=>{if(this.g.panel!=='character')return;this.draft=M.begin(this.g.p);this.render('Distribuição cancelada.');};
  $('characterApply').onclick=()=>this.apply();this.paint();
 }
 apply(){if(this.g.panel!=='character')return false;if(!M.apply(this.g.p,this.draft)){if(!M.valid(this.g.p,this.draft)){this.draft=M.begin(this.g.p);this.render('Atributos atualizados. Revise a distribuição.');}return false;}this.draft=M.begin(this.g.p);this.g.refreshHUD();this.g.save();this.render(this.g.storageOK?'Pontos aplicados e salvos.':'Pontos aplicados. Exporte a jornada para guardar.');return true;}
 paint(){if(this.g.panel!=='character')return;const canvas=$('characterPortrait'),hero=this.g.renderer.hero;if(!canvas||!hero.complete||!hero.naturalWidth)return;const c=canvas.getContext('2d'),gradient=c.createRadialGradient(96,80,10,96,96,100);gradient.addColorStop(0,'#65513b');gradient.addColorStop(1,'#171514');c.clearRect(0,0,192,192);c.fillStyle=gradient;c.fillRect(0,0,192,192);c.drawImage(hero,225,8,185,205,0,0,192,212);}
}
window.MythosCharacter=MythosCharacter;
})();
